def dlouha_slova(text, minimum):
    vysledek = []
    # split a cyklus spojíme s podmínkou.
    for slovo in text.split():
        if len(slovo) >= minimum:
            vysledek.append(slovo)
    return vysledek


# Prázdný text přirozeně vrátí prázdný seznam.
print(dlouha_slova("Na louce roste tráva", 5))
print(dlouha_slova("", 5))
